'use strict';
(()=>{
  const PAGE_SIZE=24,VERSION_LABELS={character:'Character',effects:'With effects',effectsOnly:'Effects only'};
  const $=id=>document.getElementById(id),params=new URLSearchParams(location.search);
  const state={items:[],filtered:[],page:Math.max(1,Number(params.get('page'))||1),current:null,view:'character',imageToken:0,downloadBusy:false};
  const ui={grid:$('illustration-grid'),search:$('illustration-search'),variant:$('illustration-variant'),artwork:$('illustration-artwork'),dialog:$('illustration-detail'),image:$('detail-image'),imageState:$('detail-image-state'),view:$('detail-view'),download:$('detail-download'),downloadStatus:$('detail-download-status')};
  const text=(tag,value,className)=>{const el=document.createElement(tag);el.textContent=value??'';if(className)el.className=className;return el;};
  const safeURL=value=>{if(typeof value!=='string'||!value)return null;try{const url=new URL(value,document.baseURI);return ['http:','https:'].includes(url.protocol)?url.href:null;}catch{return null;}};
  const asFile=value=>typeof value==='string'?{url:value}:value&&typeof value==='object'?value:null;
  const readableBytes=value=>{const bytes=Number(value);if(!Number.isFinite(bytes)||bytes<0)return '';return bytes>=1e9?(bytes/1e9).toFixed(2)+' GB':bytes>=1e6?(bytes/1e6).toFixed(1)+' MB':bytes>=1e3?(bytes/1e3).toFixed(1)+' KB':bytes.toLocaleString()+' B';};
  const imageDescription=(file,width,height)=>[width&&height?Number(width).toLocaleString()+' × '+Number(height).toLocaleString()+' px':'',file?.bytes!=null?readableBytes(file.bytes):'','transparent PNG'].filter(Boolean).join(' · ');
  function fileFor(item,key){const file=asFile(item?.files?.[key]);return file&&safeURL(file.url||file.path)?{...file,url:safeURL(file.url||file.path)}:null;}
  function filesFor(item){return Object.keys(VERSION_LABELS).filter(key=>fileFor(item,key));}
  function previewFor(item){const value=item.preview&&typeof item.preview==='object'?item.preview.url:item.preview;return safeURL(value)||fileFor(item,'character')?.url||fileFor(item,'effects')?.url||null;}
  const hasEffects=item=>!!(fileFor(item,'effects')||fileFor(item,'effectsOnly'));
  const titleFor=item=>item.heroName||item.name||item.id;
  const variantFor=item=>String(item.variant||'Unclassified');
  const matchesQuery=(item,q)=>[item.name,item.heroName,item.id,item.sourceBundle,...(item.aliases||[])].filter(Boolean).join(' ').toLocaleLowerCase().includes(q);
  function urlState(){const p=new URLSearchParams();if(ui.search.value.trim())p.set('q',ui.search.value.trim());if(ui.variant.value)p.set('variant',ui.variant.value);if(ui.artwork.value)p.set('artwork',ui.artwork.value);if(state.page>1)p.set('page',state.page);if(state.current){p.set('id',state.current.id);if(state.view!=='character')p.set('view',state.view);}history.replaceState(null,'',location.pathname+(p.size?'?'+p:'')+location.hash);}
  function fillFilters(){const variants=[...new Set(state.items.map(variantFor))].sort((a,b)=>a.localeCompare(b));for(const value of variants){const option=text('option',value);option.value=value;ui.variant.append(option);}ui.search.value=params.get('q')||'';if(variants.includes(params.get('variant')))ui.variant.value=params.get('variant');if(['effects','character'].includes(params.get('artwork')))ui.artwork.value=params.get('artwork');}
  function updateResults(resetPage=true){if(resetPage)state.page=1;const q=ui.search.value.trim().toLocaleLowerCase();state.filtered=state.items.filter(item=>(!q||matchesQuery(item,q))&&(!ui.variant.value||variantFor(item)===ui.variant.value)&&(!ui.artwork.value||(ui.artwork.value==='effects'?hasEffects(item):fileFor(item,'character')&&!hasEffects(item))));const pages=Math.max(1,Math.ceil(state.filtered.length/PAGE_SIZE));state.page=Math.min(pages,state.page);ui.grid.replaceChildren();for(const item of state.filtered.slice((state.page-1)*PAGE_SIZE,state.page*PAGE_SIZE))ui.grid.append(makeCard(item));ui.grid.setAttribute('aria-busy','false');$('illustration-count').textContent=state.filtered.length.toLocaleString()+' illustration'+(state.filtered.length===1?'':'s')+(state.filtered.length!==state.items.length?' · '+state.items.length.toLocaleString()+' in collection':'');$('illustration-empty').hidden=!!state.filtered.length;$('illustration-pagination').hidden=pages<=1;$('illustration-page').textContent='Page '+state.page+' of '+pages;$('illustration-previous').disabled=state.page<=1;$('illustration-next').disabled=state.page>=pages;urlState();}
  function makeCard(item){const article=text('article','','illustration-card'),button=text('button','','illustration-card-button');button.type='button';button.dataset.id=item.id;button.setAttribute('aria-label','View '+titleFor(item)+' · '+variantFor(item));const picture=text('span','','card-picture'),preview=previewFor(item);if(preview){const image=new Image();image.alt='';image.loading='lazy';image.decoding='async';image.width=240;image.height=280;image.src=preview;image.addEventListener('error',()=>{image.remove();picture.append(text('span','Preview unavailable · open for details','image-status'));},{once:true});picture.append(image);}else picture.append(text('span',item.status==='unavailable'?'Artwork unavailable':'Preview not available','image-status'));const copy=text('span','','card-copy');copy.append(text('strong',titleFor(item)),text('span',variantFor(item),'card-variant'));if(item.id!==titleFor(item))copy.append(text('span',item.id,'card-identifier'));const tags=text('span','','card-tags');if(filesFor(item).length){tags.append(text('span','Transparent PNG','card-tag'));if(hasEffects(item))tags.append(text('span','Effects included','card-tag'));}else tags.append(text('span','Unavailable','card-tag unavailable'));copy.append(tags);button.append(picture,copy);button.onclick=()=>openDetail(item);article.append(button);return article;}
  function openDetail(item,requestedView){state.current=item;const keys=filesFor(item);state.view=keys.includes(requestedView)?requestedView:keys.includes('character')?'character':keys[0]||'character';$('detail-title').textContent=titleFor(item);$('detail-variant').textContent=variantFor(item);$('detail-id').textContent=item.id;$('detail-source').textContent=item.sourceBundle||'Not recorded';ui.view.replaceChildren();for(const key of keys){const option=text('option',VERSION_LABELS[key]);option.value=key;ui.view.append(option);}ui.view.disabled=keys.length<2;if(!keys.length){const option=text('option','No downloadable artwork');option.value='character';ui.view.append(option);}ui.view.value=state.view;$('detail-notes').replaceChildren();const notes=Array.isArray(item.notes)?item.notes:item.notes?[item.notes]:[];for(const note of notes)$('detail-notes').append(text('p',typeof note==='string'?note:note.text||''));if(!keys.length&&!notes.length)$('detail-notes').append(text('p','This illustration has no verified downloadable export yet.'));$('detail-related').replaceChildren();if(item.heroId){const a=text('a','Character profile');a.href='character.html?id='+encodeURIComponent(item.heroId);$('detail-related').append(a);}if(item.sourceBundle){const a=text('a','Find source files');a.href='files.html?section=decrypted&scope=path&q='+encodeURIComponent(item.sourceBundle);$('detail-related').append(a);}$('detail-download-links').replaceChildren();for(const key of keys){const button=text('button','Download '+VERSION_LABELS[key].toLowerCase()+' PNG');button.type='button';button.dataset.downloadVersion=key;button.onclick=()=>downloadFile(item,key);$('detail-download-links').append(button);}ui.downloadStatus.textContent='';$('detail-copy-link').textContent='Copy illustration link';refreshPreview();if(!ui.dialog.open)ui.dialog.showModal();urlState();}
  async function refreshPreview(fullResolution=false){
    const token=++state.imageToken,item=state.current,key=state.view,file=fileFor(item,key),fullButton=$('detail-full-preview');
    ui.image.hidden=true;ui.image.removeAttribute('src');ui.imageState.hidden=false;ui.download.disabled=!file||state.downloadBusy;
    $('detail-size').textContent=file?imageDescription(file,file.width,file.height):'';
    const compact=safeURL(file?.preview),useFull=fullResolution||!compact||compact===file?.url;
    fullButton.disabled=!file||useFull;fullButton.textContent=fullResolution?'Loading full-resolution preview…':useFull?'Full-resolution preview':'Load full-resolution preview';
    $('detail-preview-kind').textContent=useFull?'Full-resolution preview':'Compact preview';
    if(!file){ui.imageState.textContent='No verified export is available for this illustration.';$('detail-preview-kind').textContent='Preview unavailable';return;}
    ui.imageState.textContent='Loading '+(fullResolution?'full-resolution ':'')+VERSION_LABELS[key].toLowerCase()+'…';
    ui.image.alt=titleFor(item)+' · '+variantFor(item)+' · '+VERSION_LABELS[key];ui.image.src=useFull?file.url:compact;
    try{
      await ui.image.decode();if(token!==state.imageToken)return;ui.image.hidden=false;ui.imageState.hidden=true;
      if(useFull)fullButton.textContent='Full-resolution preview loaded';
      if(!file.width||!file.height)$('detail-size').textContent=imageDescription(file,ui.image.naturalWidth,ui.image.naturalHeight);
    }catch{
      if(token!==state.imageToken)return;ui.image.hidden=true;ui.imageState.textContent='This image could not be loaded. You can retry this version or use its download.';
      if(fullResolution){fullButton.disabled=false;fullButton.textContent='Retry full-resolution preview';}
    }
  }
  function fileName(item,key,file){const supplied=file.filename&&String(file.filename).split(/[\\/]/).pop();return (supplied||item.id+'-'+key).replace(/\.(?:png|webp|avif)$/i,'').replace(/[^\p{L}\p{N}._-]+/gu,'-')+'.png';}
  async function pngBlob(file){const response=await fetch(file.url);if(!response.ok)throw Error('The image server returned '+response.status+'.');const blob=await response.blob(),signature=new Uint8Array(await blob.slice(0,8).arrayBuffer());if([137,80,78,71,13,10,26,10].every((v,i)=>signature[i]===v))return new Blob([blob],{type:'image/png'});const objectURL=URL.createObjectURL(blob),image=new Image();try{image.src=objectURL;await image.decode();const canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;const context=canvas.getContext('2d');if(!context)throw Error('PNG conversion is unavailable in this browser.');context.drawImage(image,0,0);return await new Promise((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(Error('PNG conversion failed.')),'image/png'));}finally{URL.revokeObjectURL(objectURL);}}
  async function downloadFile(item,key){
    if(state.downloadBusy)return;
    const file=fileFor(item,key);if(!file)return;
    const remote=new URL(file.url).origin!==location.origin,format=String(file.format||new URL(file.url).pathname.split('.').pop()).toLowerCase();
    // Release attachments download through ordinary navigation; cross-origin fetch would require CORS.
    if(remote&&format==='png'){
      const link=document.createElement('a');link.href=file.url;link.download=fileName(item,key,file);link.target='_blank';link.rel='noopener';document.body.append(link);link.click();link.remove();
      ui.downloadStatus.textContent='Opened the original transparent PNG download.';return;
    }
    state.downloadBusy=true;ui.download.disabled=true;document.querySelectorAll('[data-download-version]').forEach(button=>button.disabled=true);ui.downloadStatus.textContent='Preparing transparent PNG…';
    try{const blob=await pngBlob(file),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=fileName(item,key,file);document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);ui.downloadStatus.textContent=VERSION_LABELS[key]+' PNG is ready. Transparency is preserved.';}
    catch(error){ui.downloadStatus.replaceChildren(text('span','Download could not be prepared. '+error.message+' '));if(format==='png'){const a=text('a','Open the original PNG');a.href=file.url;a.target='_blank';a.rel='noopener';ui.downloadStatus.append(a);}else ui.downloadStatus.append(text('span','Try again when the image is available.'));}
    finally{state.downloadBusy=false;ui.download.disabled=!fileFor(state.current,state.view);document.querySelectorAll('[data-download-version]').forEach(button=>button.disabled=false);}
  }
  async function readCatalog(){let response=await fetch('data/hero-illustrations/index.json');if(response.status===404){response=await fetch('data/hero-illustrations/index.json.gz');if(!response.ok)throw Error('The illustration catalogue is not available ('+response.status+').');if(typeof DecompressionStream==='undefined')throw Error('This browser cannot read the compressed illustration catalogue.');return JSON.parse(await new Response(response.body.pipeThrough(new DecompressionStream('gzip'))).text());}if(!response.ok)throw Error('The illustration catalogue is not available ('+response.status+').');return response.json();}
  function showSummary(catalog){
    const ready=state.items.filter(item=>filesFor(item).length).length,heroCount=Number(catalog.summary?.playableHeroOrigins||catalog.summary?.heroCount||0);
    const coverage=heroCount?' · '+heroCount.toLocaleString()+' playable heroes covered':'';
    $('collection-summary').replaceChildren(text('strong',state.items.length.toLocaleString()+' illustrations'),text('span',coverage+' · '+ready.toLocaleString()+' ready to download'+(catalog.version?' · '+catalog.version:'')));
    const packs=Array.isArray(catalog.packs)?catalog.packs:[];
    for(const pack of packs){const url=safeURL(pack.url||pack.href);if(!url)continue;const a=text('a',pack.label||pack.name||'Download illustration pack');if(pack.bytes!=null)a.append(text('span',' · '+readableBytes(pack.bytes)+' ZIP','pack-size'));a.href=url;if(new URL(url).origin!==location.origin){a.target='_blank';a.rel='noopener';}if(pack.filename)a.download=pack.filename;$('collection-packs').append(a);}
    $('collection-packs').hidden=!$('collection-packs').childElementCount;
  }
  let searchTimer;ui.search.addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>updateResults(),120);});ui.variant.onchange=()=>updateResults();ui.artwork.onchange=()=>updateResults();$('illustration-filters').onsubmit=event=>{event.preventDefault();clearTimeout(searchTimer);updateResults();};$('illustration-reset').onclick=()=>{ui.search.value='';ui.variant.value='';ui.artwork.value='';updateResults();ui.search.focus();};for(const [id,step]of[['illustration-previous',-1],['illustration-next',1]])$(id).onclick=()=>{state.page+=step;updateResults(false);$('illustration-filters').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});};ui.view.onchange=()=>{state.view=ui.view.value;ui.downloadStatus.textContent='';refreshPreview();urlState();};document.querySelectorAll('[name=preview-background]').forEach(input=>input.onchange=()=>{$('detail-canvas').dataset.background=input.value;});ui.download.onclick=()=>downloadFile(state.current,state.view);$('detail-full-preview').onclick=()=>refreshPreview(true);$('detail-close').onclick=()=>ui.dialog.close();ui.dialog.addEventListener('click',event=>{if(event.target===ui.dialog){const box=ui.dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)ui.dialog.close();}});ui.dialog.addEventListener('close',()=>{state.current=null;++state.imageToken;ui.image.removeAttribute('src');urlState();});$('detail-copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);$('detail-copy-link').textContent='Link copied';}catch{$('detail-copy-link').textContent='Copy the URL from your address bar';}};
  readCatalog().then(catalog=>{const rows=Array.isArray(catalog)?catalog:catalog.illustrations||catalog.entries||[];if(!Array.isArray(rows)||!rows.length)throw Error('The illustration catalogue is empty.');state.items=rows.filter(item=>item&&typeof item.id==='string').sort((a,b)=>titleFor(a).localeCompare(titleFor(b))||variantFor(a).localeCompare(variantFor(b))||a.id.localeCompare(b.id));fillFilters();showSummary(catalog);const id=params.get('id'),view=params.get('view');updateResults(false);if(id){const item=state.items.find(row=>row.id===id);if(item)openDetail(item,view);}}).catch(error=>{ui.grid.setAttribute('aria-busy','false');$('collection-summary').textContent='The collection could not be loaded.';$('collection-error').hidden=false;$('collection-error').textContent=error.message+' Please reload to try again.';});
})();
